select t.tool_id, t.project_id, t.tool_display_name, t.tool_chinese_name, t.tool_desc, t.icon, t.request_info, t.auth_info, t.visibility, t.input_schema, t.output_schema, t.is_input_list, t.is_output_list, t.intf_type, t.type, t.test_status, t.last_version_id, t.auth_required, t.metadata, t.creator, t.customize_node, t.creator_id, t.created_on, t.updated_on, c.id as c_id, c.project_id as c_project_id, c.user_id as c_user_id, c.auth_keys as c_auth_keys, CASE WHEN c.auth_keys IS NULL THEN CASE WHEN t.type = 'custom' THEN 'NONE' WHEN t.auth_required = false THEN 'NONE' ELSE 'UNAUTHENTICATED' END ELSE 'AUTHENTICATED' END as credential_status from t_tool t LEFT JOIN t_credential c on t.tool_id = c.resource_id and c.resource_type = 'tool' and (c.workspace_id is null or c.workspace_id = #{workspaceId,jdbcType=VARCHAR}) where 1=1
